/* Independent cross-check: literal transcription of the engine's packed
 * structs + htons/memcmp ordering, hashed with OpenSSL SHA1. */
#include <arpa/inet.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

static const char b64[] =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static void b64enc(const uint8_t *in, size_t len, char *out)
{
    size_t i, o = 0;
    for (i = 0; i + 2 < len; i += 3) {
        uint32_t v = (in[i] << 16) | (in[i + 1] << 8) | in[i + 2];
        out[o++] = b64[(v >> 18) & 63];
        out[o++] = b64[(v >> 12) & 63];
        out[o++] = b64[(v >> 6) & 63];
        out[o++] = b64[v & 63];
    }
    if (len - i == 1) {
        uint32_t v = in[i] << 16;
        out[o++] = b64[(v >> 18) & 63];
        out[o++] = b64[(v >> 12) & 63];
        out[o++] = '=';
        out[o++] = '=';
    } else if (len - i == 2) {
        uint32_t v = (in[i] << 16) | (in[i + 1] << 8);
        out[o++] = b64[(v >> 18) & 63];
        out[o++] = b64[(v >> 12) & 63];
        out[o++] = b64[(v >> 6) & 63];
        out[o++] = '=';
    }
    out[o] = '\0';
}

static void v4(uint16_t seed, const char *s, const char *d, uint8_t proto,
        uint16_t sp_in, uint16_t dp_in, char *outbuf)
{
    struct {
        uint16_t seed;
        uint32_t src;
        uint32_t dst;
        uint8_t proto;
        uint8_t pad0;
        uint16_t sp;
        uint16_t dp;
    } __attribute__((__packed__)) ipv4;

    uint32_t src, dst;
    inet_pton(AF_INET, s, &src);
    inet_pton(AF_INET, d, &dst);
    uint16_t sp = htons(sp_in), dp = htons(dp_in);

    ipv4.seed = htons(seed);
    if (ntohl(src) < ntohl(dst) || (src == dst && ntohs(sp) < ntohs(dp))) {
        ipv4.src = src; ipv4.dst = dst; ipv4.sp = sp; ipv4.dp = dp;
    } else {
        ipv4.src = dst; ipv4.dst = src; ipv4.sp = dp; ipv4.dp = sp;
    }
    ipv4.proto = proto;
    ipv4.pad0 = 0;

    uint8_t hash[20];
    SHA1((const unsigned char *)&ipv4, sizeof(ipv4), hash);
    strcpy(outbuf, "1:");
    b64enc(hash, sizeof(hash), outbuf + 2);
}

static void v6(uint16_t seed, const char *s, const char *d, uint8_t proto,
        uint16_t sp_in, uint16_t dp_in, char *outbuf)
{
    struct {
        uint16_t seed;
        uint32_t src[4];
        uint32_t dst[4];
        uint8_t proto;
        uint8_t pad0;
        uint16_t sp;
        uint16_t dp;
    } __attribute__((__packed__)) ipv6;

    uint8_t src[16], dst[16];
    inet_pton(AF_INET6, s, src);
    inet_pton(AF_INET6, d, dst);
    uint16_t sp = htons(sp_in), dp = htons(dp_in);

    ipv6.seed = htons(seed);
    int cmp_r = memcmp(src, dst, 16);
    if ((cmp_r < 0) || (cmp_r == 0 && ntohs(sp) < ntohs(dp))) {
        memcpy(&ipv6.src, src, 16); memcpy(&ipv6.dst, dst, 16);
        ipv6.sp = sp; ipv6.dp = dp;
    } else {
        memcpy(&ipv6.src, dst, 16); memcpy(&ipv6.dst, src, 16);
        ipv6.sp = dp; ipv6.dp = sp;
    }
    ipv6.proto = proto;
    ipv6.pad0 = 0;

    uint8_t hash[20];
    SHA1((const unsigned char *)&ipv6, sizeof(ipv6), hash);
    strcpy(outbuf, "1:");
    b64enc(hash, sizeof(hash), outbuf + 2);
}

/* argv: seed src dst proto sp dp */
int main(int argc, char **argv)
{
    if (argc != 7) return 1;
    uint16_t seed = (uint16_t)atoi(argv[1]);
    uint8_t proto = (uint8_t)atoi(argv[4]);
    uint16_t sp = (uint16_t)atoi(argv[5]), dp = (uint16_t)atoi(argv[6]);
    char out[64];
    if (strchr(argv[2], ':'))
        v6(seed, argv[2], argv[3], proto, sp, dp, out);
    else
        v4(seed, argv[2], argv[3], proto, sp, dp, out);
    printf("%s\n", out);
    fprintf(stderr, "sizeof v4=14? v6=40?\n");
    return 0;
}

