import socket, struct, sys

def key(seed, s, d, proto, sp, dp):
    fam = socket.AF_INET6 if ":" in s else socket.AF_INET
    src = socket.inet_pton(fam, s)
    dst = socket.inet_pton(fam, d)
    if src < dst or (src == dst and sp < dp):
        a, b, pa, pb = src, dst, sp, dp
    else:
        a, b, pa, pb = dst, src, dp, sp
    return struct.pack(">H", seed) + a + b + struct.pack(">BBHH", proto, 0, pa, pb)

cases = [
    (0, "1.2.3.4", "5.6.7.8", 6, 12345, 80),
    (0, "5.6.7.8", "1.2.3.4", 6, 80, 12345),
    (0, "2001:db8::1", "2001:db8::2", 6, 12345, 443),
    (0, "10.0.0.1", "10.0.0.1", 6, 443, 40000),
]
for c in cases:
    k = key(*c)
    print(len(k), k.hex())

